INSERT INTO public.erp_settings (key, value, scope, description, value_pattern, value_example) VALUES
  ('acct.aging_alert', 'on', 'ADMIN', '받을 돈 · 갚을 돈 오래됨 운영 알림(v10.401) — off 면 알리지 않음(표는 그대로 봄).', '^(on|off)$', 'on'),
  ('acct.aging_alert_days', '90', 'ADMIN', '받을 돈 · 갚을 돈 오래됨 운영 알림 기준 일수(v10.401 · docs/538) — 이 일수를 넘긴 외상매출금 · 미지급금이 있으면 ACCT_AGING_OVER(거래처 · 계정마다 한 번 · 사라지면 풀림 · 30 ~ 365 · 처음 90).', '^([3-9][0-9]|[1-2][0-9]{2}|3[0-5][0-9]|36[0-5])$', '90'),
  ('acct.ap_pay_days', '30', 'ADMIN', '자금 흐름 — 미지급금(매입 · 경비)을 전표 날 며칠 뒤에 갚는지(v10.394 · 0 ~ 120 · 처음 30).', '^([0-9]|[1-9][0-9]|1[01][0-9]|120)$', '30'),
  ('acct.asset_life_defaults', 'FIXTURE:60,VEHICLE:60,TOOL:60,MACHINE:96,BUILDING:480,SOFTWARE:60', 'ADMIN', 'v10.418 고정자산 종류별 기본 내용연수(달 · 법인세법 기준내용연수 · 정액법 · 잔존가치 0) — 자산 넣을 때 처음 값', '^([A-Z_]{2,20}:[0-9]{1,3})(,[A-Z_]{2,20}:[0-9]{1,3})*$', 'FIXTURE:60,BUILDING:480'),
  ('acct.bank_feed', 'off', 'ADMIN', '은행 거래내역 자동 조회(v10.467 · D264) — 처음 off · on 이면 매일 06:40 등록한 회사 계좌의 거래내역을 은행 맞추기로 들여옴 · 켜기 SUPER', '^(on|off)$', 'off'),
  ('acct.bank_feed_days', '3', 'ADMIN', '은행 거래내역 자동 조회 — 한 번에 묻는 날 수(오늘 포함 · 1 ~ 31 · 처음 3 · v10.467)', '^([1-9]|[12][0-9]|3[01])$', '3'),
  ('acct.bank_feed_mode', 'ASSUME', 'ADMIN', '은행 거래내역 자동 조회 방식(v10.467) — ASSUME 은 금융결제원에 묻지 않고 간주 2줄 · LIVE 는 금융결제원 키(FIRMBANK_CLIENT_ID · FIRMBANK_USER_TOKEN) · .env FIRMBANK_ORG_CODE 가 있어야', '^(ASSUME|LIVE)$', 'ASSUME'),
  ('acct.bank_match_days', '3', 'ADMIN', '은행 거래 맞추기 날짜 폭(v10.388 · docs/525) — 통장 날짜와 전표 날짜가 이 일수 안이면 후보(1 ~ 14 · 처음 3).', '^([1-9]|1[0-4])$', '3'),
  ('acct.biz_status_check', 'off', 'ADMIN', '거래처 휴폐업 조회(국세청 · 공공데이터포털 키 NTS_SERVICE_KEY) — on 이면 거래처 화면 「조회」 · 매일 06:10 30일 지난 거래처 50곳 다시 조회 · 휴업 · 폐업이면 운영 알림(v10.431 · D254 · 처음 off)', '^(on|off)$', 'off'),
  ('acct.budget_alert', 'on', 'ADMIN', '예산 넘음 운영 알림(v10.399 · docs/536) — 비용 계정 달 실적이 예산을 넘으면 ACCT_BUDGET_OVER(달 · 계정 한 번). off 면 알리지 않음.', '^(on|off)$', 'on'),
  ('acct.card_alert', 'on', 'ADMIN', '법인카드 한도 알림(v10.453 · D261) — on 이면 매일 09:40 이번 달 사용이 한도의 acct.card_alert_pct 를 넘은 카드를 운영 알림(ACCT_CARD_LIMIT)', '^(on|off)$', 'on'),
  ('acct.card_alert_pct', '80', 'ADMIN', '법인카드 한도 알림 기준(퍼센트 · 50 ~ 100 · 처음 80 · v10.453) — 이만큼 쓰면 한 번 · 한도를 넘으면 한 번 더', '^([5-9][0-9]|100)$', '80'),
  ('acct.card_pay_day', '15', 'ADMIN', '자금 흐름 — 법인카드 결제일(v10.394 · 1 ~ 28 · 처음 15). 그 달 쓴 것은 다음 달 이 날(영업일 아니면 다음 영업일) 나감.', '^([1-9]|1[0-9]|2[0-8])$', '15'),
  ('acct.cash_alert', 'on', 'ADMIN', '자금 흐름 운영 알림(v10.394) — off 면 ACCT_CASH_SHORT 를 넣지 않음(있던 것은 풀림).', '^(on|off)$', 'on'),
  ('acct.cash_floor', '0', 'ADMIN', '자금 흐름 — 이 금액(원) 밑으로 내려가는 날이 90일 안에 있으면 운영 알림 ACCT_CASH_SHORT(v10.394 · 처음 0 = 마이너스일 때만).', '^[0-9]{1,13}$', '5000000'),
  ('acct.cashplan_alert', 'on', 'ADMIN', '12개월 자금 계획 운영 알림(v10.476) — on 이면 매일 09:35 달 말 예상 잔액이 acct.cash_floor 밑인 첫 달을 ACCT_CASHPLAN_SHORT 로 · off 면 있던 알림 풂', '^(on|off)$', 'on'),
  ('acct.cashplan_collect_months', '1', 'ADMIN', '12개월 자금 계획(v10.476) — 예상 매출이 통장에 들어오기까지 달 수(0 ~ 3 · 처음 1 = 다음 달)', '^[0-3]$', '1'),
  ('acct.cashplan_sales', 'TARGET', 'ADMIN', '12개월 자금 계획(v10.476 · D266) — 예상 매출 기준: TARGET 매출 목표(회사 전체) · CRM 영업 기회 가중(상담 10 · 견적 30 · 계약 70%) · NONE 넣지 않음', '^(TARGET|CRM|NONE)$', 'TARGET'),
  ('acct.close_by_day', '10', 'ADMIN', '지난달 마감 기한 날(v10.390) — 이 날(한국) 뒤에도 지난달을 마감하지 않았으면 운영 알림 ACCT_UNCLOSED(1 ~ 28 · 처음 10).', '^([1-9]|1[0-9]|2[0-8])$', '10'),
  ('acct.commission_vat_included', 'off', 'ADMIN', '입점 수수료에 부가세가 들어 있음(v10.381) — 11/19 대표 「부가세 별도」 → off: 수수료가 공급가이고 부가세 10% 를 더 받음 · on 이면 수수료 ÷ 11 을 부가세로 나눔(SUPER).', '^(on|off)$', 'off'),
  ('acct.contract_accrue', 'off', 'ADMIN', 'v10.439 (D257) 고정비 자동 전표 — on 이면 매달 1일 계약 달 금액을 미지급 비용 전표로(같은 거래처 매입이 오면 반대 전표) · 다음 달 말까지 매입이 없으면 운영 알림', '^(on|off)$', 'off'),
  ('acct.control_big_amount', '10000000', 'ADMIN', 'v10.440 (D257) 내부통제 보고의 「큰 금액 전표」 기준(원 · 한 전표 차변 합)', '^[0-9]{4,12}$', '10000000'),
  ('acct.corp_doc_due_days', '30', 'ADMIN', 'v10.425 사내 문서 만료 알림 — 만료 며칠 전부터 CORP_DOC_DUE(1 ~ 180)', '^([1-9]|[1-9][0-9]|1[0-7][0-9]|180)$', '30'),
  ('acct.corp_fiscal_end', '12', 'ADMIN', '사업연도 끝 달(v10.407 · 처음 12) — 중간예납 기한 = 사업연도 시작 6개월 뒤 달 말 · 확정 신고 = 끝 달 3개월 뒤 달 말.', '^([1-9]|1[0-2])$', '12'),
  ('acct.corp_local_rate', '10', 'ADMIN', '법인 지방소득세 = 법인세의 몇 %(v10.407 · 초안 · 처음 10).', '^[0-9]{1,2}$', '10'),
  ('acct.corp_tax_brackets', '200000000:10,20000000000:20,300000000000:22,*:25', 'ADMIN', '법인세 세율 구간(v10.407 · 초안 · 세무사 확인) — 「과세표준 상한:세율%」 쉼표로 · 마지막은 *. 해마다 세법이 바뀌면 SUPER 가 고침. · v10.418 2026.1.1 이후 개시 사업연도 세율(2025 세법 개정 · 확인 필요)', E'^([0-9]{1,15}:[0-9]{1,2}(\\.[0-9])?,){0,9}\\*:[0-9]{1,2}(\\.[0-9])?$', '200000000:9,20000000000:19,300000000000:21,*:24'),
  ('acct.deadline_alert', 'on', 'ADMIN', '신고 기한 운영 알림(v10.390 · docs/527) — 원천세(매월 10일) · 부가세(acct.vat_months 의 25일) N일 전 · 지난달 마감 안 함. off 면 알리지 않음.', '^(on|off)$', 'on'),
  ('acct.deadline_days_before', '3', 'ADMIN', '신고 기한 며칠 전에 알릴지(v10.390 · 1 ~ 7 · 처음 3). 기한이 주말 · 공휴일이면 다음 영업일이 기한입니다.', '^[1-7]$', '3'),
  ('acct.deadline_payday', 'off', 'ADMIN', '급여 지급일(acct.pay_day) · 법인카드 대금일(acct.card_pay_day)도 기한 알림(ACCT_DEADLINE)으로 보낼지 — 처음 off(v10.418 · D251)', '^(on|off)$', 'off'),
  ('acct.dunning', 'off', 'ADMIN', '미수금 독촉 메일 자동 보내기(v10.436 · D256) — 처음 off · on 이면 매일 09:35 단계가 올라간 거래처에 한 번(메일 준비가 된 때만)', '^(on|off)$', 'off'),
  ('acct.exempt_invoice', 'off', 'ADMIN', '전자계산서(면세) 발행(v10.477 · D266) — 처음 off · on 이면 확정한 거래명세서의 면세 품목을 전자계산서로 따로 요청 · 발행(㉒ 전자세금계산서 어댑터 · assume.etax on 이면 간주)하고 세금계산서는 과세 · 영세 품목만 · 켜기 SUPER · 세무사 확인', '^(on|off)$', 'off'),
  ('acct.include_stub', 'off', 'ADMIN', '시험 결제(간주 · stub)도 전표로 만들기(v10.382) — 처음 off. 간주 결제가 켜진 동안은 실제 돈이 아니므로 off 를 권합니다(SUPER).', '^(on|off)$', 'off'),
  ('acct.insurance_alert', 'on', 'ADMIN', '4대보험 취득 · 상실 신고 기한(다음 달 15일) 3일 전부터 운영 알림 ACCT_INSURANCE_DUE — 직원이 있을 때만 생김(v10.422 · D252)', '^(on|off)$', 'on'),
  ('acct.leave_base_days', '15', 'ADMIN', '연차 기본 일수(v10.406 · 초안 · 노무사 확인) — 1년 이상 근무 때 해마다 생기는 날(처음 15).', '^([1-9]|[1-2][0-9]|30)$', '15'),
  ('acct.leave_first_year_monthly', '1', 'ADMIN', '1년 미만 근무 때 한 달 개근마다 생기는 날(v10.406 · 초안 · 처음 1 · 최대 11일).', '^[0-3]$', '1'),
  ('acct.leave_max_days', '25', 'ADMIN', '연차 최대 일수(v10.406 · 초안) — 근속 2년마다 1일 더하되 이 날까지(처음 25).', '^([1-9]|[1-3][0-9]|40)$', '25'),
  ('acct.pay_day', '25', 'ADMIN', '급여 지급일(v10.403 · docs/540) — 매달 이 날(1 ~ 28 · 처음 25 · 대표가 알려 주면 바꿈). 새 달 급여 대장의 지급일 처음 값 · 자금 흐름 나갈 돈.', '^([1-9]|1[0-9]|2[0-8])$', '25'),
  ('acct.payslip_mail', 'off', 'ADMIN', '급여명세서 알림 메일(v10.447 · D259) — 처음 off · on 이면 SUPER 가 「알림 보내기」로 연결된 직원 계정 메일에 「명세서가 나왔습니다」만(금액 없음)', '^(on|off)$', 'off'),
  ('acct.pg_match_days', '2', 'ADMIN', 'PG 정산 맞추기 날짜 폭(v10.404) — 결제일과 전표 날짜가 이 일수 안이면 후보(0 ~ 7 · 처음 2).', '^[0-7]$', '2'),
  ('acct.pg_settle_days', '2', 'ADMIN', '자금 흐름 — PG 결제 뒤 며칠(영업일)에 통장에 들어오는지(v10.394 · docs/531 · 0 ~ 14 · 처음 2). PG 사 계약을 보고 맞추십시오.', '^([0-9]|1[0-4])$', '2'),
  ('acct.pg_unsettled_days', '7', 'ADMIN', 'PG 정산 안 들어온 결제 알림(v10.404 · docs/541) — PG 정산 받을 돈 전표가 이 일수 지나도 PG 정산 줄과 맞지 않으면 운영 알림 ACCT_PG_UNSETTLED(1 ~ 60 · 처음 7).', '^([1-9]|[1-5][0-9]|60)$', '7'),
  ('acct.policy_basis', 'GENERAL_2026', 'ADMIN', 'v10.418 세무 · 노무 값의 근거 — GENERAL_2026(일반 원칙 · 2026 기준 · 대표 11/19) · 세무사 확인 뒤 CONFIRMED', '^(GENERAL_2026|CONFIRMED)$', 'GENERAL_2026'),
  ('acct.receipt_ai', 'off', 'ADMIN', 'v10.438 (D257) 영수증 사진 자동 입력 — on 이면 매입 · 경비 증빙 그림에서 날짜 · 공급자 · 금액을 읽어 칸 채움 제안(저장은 사람이 확인) · AI 전체 스위치 · 월 상한 안에서만', '^(on|off)$', 'off'),
  ('acct.receipt_ai_mode', 'ASSUME', 'ADMIN', 'v10.438 (D257) 영수증 읽기 방식 — ASSUME(간주 · 밖으로 안 나감) · AI(운영 화면 AI 키로 읽음)', '^(ASSUME|AI)$', 'ASSUME'),
  ('acct.reorder', 'on', 'ADMIN', '안전 재고 · 재주문(v10.478 · D266) — on 이면 매시간 판매용 재고 + 발주 중이 최소 밑인 직판 옵션을 운영 알림(STOCK_REORDER) · 재주문 초안(발주는 사람이 넣음) · 규칙이 없으면 아무것도 안 함', '^(on|off)$', 'on'),
  ('acct.req_tolerance_pct', '10', 'ADMIN', '품의 금액보다 이만큼(%)까지 더 써도 연결 허용 — 넘으면 다시 품의(v10.410 · D249)', '^([0-9]|[1-4][0-9]|50)$', '10'),
  ('acct.seller_pay_days', '3', 'ADMIN', '자금 흐름 — 입점 판매자 정산을 확정 며칠 뒤(영업일 아니면 다음 영업일)에 지급하는지(v10.394 · 0 ~ 30 · 처음 3).', '^([0-9]|[12][0-9]|30)$', '3'),
  ('acct.start_on', '2026-11-01', 'ADMIN', '자동 전표 시작일(v10.382 · docs/518) — 이 날(한국) 뒤 돈 흐름만 전표로 만듦. 회계 프로그램에 이미 넣은 달은 빼도록 고칩니다(SUPER).', '^[0-9]{4}-[0-9]{2}-[0-9]{2}$', '2026-11-01'),
  ('acct.sub_vat_included', 'on', 'ADMIN', '구독 · 소개코드 결제한 금액에 부가세가 들어 있음(v10.381) — 11/19 대표 「부가세 별도」 → 결제는 요금 + 부가세(⑩)이므로 결제 금액 ÷ 11 을 부가세로 나눔(on). off 면 나누지 않음(SUPER).', '^(on|off)$', 'on'),
  ('acct.taxinbox', 'off', 'ADMIN', 'v10.432 매입 세금계산서 가져오기 켜기(처음 off · SUPER) — 켜면 매일 08:10 지난 7일을 가져옴 · 화면 「가져오기」', '^(on|off)$', 'off'),
  ('acct.taxinbox_mode', 'ASSUME', 'ADMIN', 'v10.432 ASSUME = 업체에 묻지 않고 간주 줄 · LIVE = 연동 업체 API(키 · 주소 · 사업자번호가 있어야 함)', '^(ASSUME|LIVE)$', 'ASSUME'),
  ('acct.taxinbox_provider', 'GENERIC', 'ADMIN', 'v10.432 연동 업체(응답 칸 이름 기본값만 다름 · 업체 문서로 확인 필요 · .env TAXINBOX_MAP 로 고침)', '^(GENERIC|POPBILL|BAROBILL)$', 'GENERIC'),
  ('acct.transfer', 'off', 'ADMIN', '대량 이체 「보내기」(v10.454 · D261) — 처음 off · 만들기 · 승인은 꺼져도 됨 · 켜기 SUPER', '^(on|off)$', 'off'),
  ('acct.transfer_max', '50000000', 'ADMIN', '대량 이체 한 묶음 합계 상한(원 · v10.454 · 처음 5천만 원)', '^[0-9]{5,12}$', '50000000'),
  ('acct.transfer_mode', 'ASSUME', 'ADMIN', '대량 이체 방식(v10.454) — ASSUME 은 은행에 보내지 않고 간주 결과(전표 없음) · LIVE 는 금융결제원 키(FIRMBANK_CLIENT_ID · FIRMBANK_CLIENT_SECRET) · .env FIRMBANK_ORG_CODE · FIRMBANK_CNTR_ACCOUNT 가 있어야', '^(ASSUME|LIVE)$', 'ASSUME'),
  ('acct.vat_efile_credit', '10000', 'ADMIN', '부가세 전자신고 세액공제(v10.400 · docs/537) — 확정 신고 때 납부세액에서 뺄 금액(원 · 처음 10,000 · 0 이면 안 뺌). 세법 기본값 초안 — 세무사 확인.', '^[0-9]{1,7}$', '10000'),
  ('acct.vat_months', '1,4,7,10', 'ADMIN', '부가세 신고 달(v10.390) — 그 달 25일이 기한. 처음 1 · 4 · 7 · 10월(예정 · 확정 신고). 쉼표로 1 ~ 12.', '^(1[0-2]|[1-9])(,(1[0-2]|[1-9])){0,11}$', '1,4,7,10'),
  ('acct.vehicle_dep_limit', '8000000', 'ADMIN', '업무용 차량(v10.475) — 업무 사용 감가상각비(리스 · 렌트는 상당액) 연 한도(원 · 1대 · 보유 달 수로 나눔 · 넘은 몫은 다음 해로 이월) · 일반 원칙 800만 원 · 세무사 확인 · SUPER 고침', '^[0-9]{1,10}$', '8000000'),
